# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">CUMHURİYET DÖNEMİ SAF (ÖZ) ŞİİR ANLAYIŞININ TEMEL ÖZELLİKLERİ</text>\n  <rect x="25" y="48" width="315" height="185" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">BİÇİM, DİL VE ESTETİK İLKELER</text>\n  <text x="42" y="98" font-size="11" fill="#4c1d95">• <tspan font-weight="bold">Batılı Kaynak:</tspan> Fransız Sembolistleri (Valéry, Mallarmé)</text>\n  <text x="42" y="120" font-size="11" fill="#4c1d95">• <tspan font-weight="bold">Yerli Öncüler:</tspan> Ahmet Haşim ve Yahya Kemal Beyatlı</text>\n  <text x="42" y="142" font-size="11" fill="#4c1d95">• <tspan font-weight="bold">Biçim Kusursuzluğu:</tspan> İç ahenk, musiki, ritim ve ölçü</text>\n  <text x="42" y="164" font-size="11" fill="#4c1d95">• <tspan font-weight="bold">Sanat Anlayışı:</tspan> İdeoloji ve didaktizmden uzak, estetik</text>\n  <text x="42" y="186" font-size="11" fill="#4c1d95">• <tspan font-weight="bold">Anlatım:</tspan> İmge, sembol, sezgi ve zengin çağrışım gücü</text>\n  <text x="182" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#6d28d9">İlke: "Şiirde her şeyden önce musiki ve estetik"</text>\n  <rect x="360" y="48" width="315" height="185" rx="10" fill="#fce7f3" stroke="#db2777" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#9d174d">BAŞLICA TEMALAR VE TEMSİLCİLER</text>\n  <text x="377" y="98" font-size="11" fill="#831843">• <tspan font-weight="bold">Temalar:</tspan> Zaman, rüya, ölüm, yaşama sevinci, yalnızlık,</text>\n  <text x="387" y="116" font-size="11" fill="#831843">çocukluk özlemi, aşk, sonsuzluk ve metafizik ürperti</text>\n  <text x="377" y="140" font-size="11" fill="#831843">• <tspan font-weight="bold">Temsilciler:</tspan> Necip Fazıl Kısakürek, Ahmet Hamdi Tanpınar,</text>\n  <text x="387" y="158" font-size="11" fill="#831843">Cahit Sıtkı Tarancı, Ahmet Muhip Dıranas, Ziya Osman</text>\n  <text x="387" y="176" font-size="11" fill="#831843">Saba, Asaf Halet Çelebi, Yedi Meşaleciler</text>\n  <text x="517" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">Ölçü: Çoğunlukla modernleştirilmiş Hece Ölçüsü</text>\n</svg>', '<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SAF ŞİİR TEMSİLCİLERİ (1): NECİP FAZIL, TANPINAR VE DIRANAS</text>\n  <rect x="20" y="45" width="210" height="182" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Necip Fazıl Kısakürek</text>\n  <text x="32" y="92" font-size="11" fill="#1e3a8a">• Unvan: Kaldırımlar Şairi</text>\n  <text x="32" y="114" font-size="11" fill="#1e3a8a">• Tema: Metafizik ürperti, korku,</text>\n  <text x="42" y="130" font-size="11" fill="#1e3a8a">yalnızlık, ruhsal bunalım, tasavvuf</text>\n  <text x="32" y="152" font-size="11" fill="#1e3a8a">• Dergi: Ağaç ve Büyük Doğu</text>\n  <text x="32" y="176" font-size="11" font-weight="bold" fill="#1d4ed8">Şiir: Örümcek Ağı, Kaldırımlar,</text>\n  <text x="32" y="194" font-size="11" font-weight="bold" fill="#1d4ed8">Ben ve Ötesi, Çile</text>\n  <rect x="245" y="45" width="210" height="182" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Ahmet Hamdi Tanpınar</text>\n  <text x="257" y="92" font-size="11" fill="#14532d">• Etki: Yahya Kemal &amp; Valéry</text>\n  <text x="257" y="114" font-size="11" fill="#14532d">• Felsefe: Bergson (Yekpare zaman)</text>\n  <text x="257" y="136" font-size="11" fill="#14532d">• Tema: Zaman, rüya, musiki, tarih</text>\n  <text x="257" y="158" font-size="11" fill="#14532d">• Ünlü Şiir: Bursa\'da Zaman,</text>\n  <text x="267" y="174" font-size="11" fill="#14532d">Ne İçindeyim Zamanın</text>\n  <text x="257" y="198" font-size="11" font-weight="bold" fill="#15803d">Şiir Eseri: Şiirler</text>\n  <rect x="470" y="45" width="210" height="182" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Ahmet Muhip Dıranas</text>\n  <text x="482" y="92" font-size="11" fill="#78350f">• Etki: Fransız Sembolizmi</text>\n  <text x="482" y="114" font-size="11" fill="#78350f">• Biçim: Esnek duraklı hece ölçüsü</text>\n  <text x="482" y="136" font-size="11" fill="#78350f">• Tema: Aşk, doğa, hüzün, güzellik</text>\n  <text x="482" y="158" font-size="11" fill="#78350f">• Ünlü Şiir: Fahriye Abla, Olvido,</text>\n  <text x="492" y="174" font-size="11" fill="#78350f">Kar, Serenad, Ağrı</text>\n  <text x="482" y="198" font-size="11" font-weight="bold" fill="#b45309">Eser: Şiirler, Gölgeler (Oyun)</text>\n</svg>', '<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SAF ŞİİR TEMSİLCİLERİ (2): CAHİT SITKI, ZİYA OSMAN VE ASAF HALET</text>\n  <rect x="20" y="45" width="210" height="182" rx="10" fill="#fce7f3" stroke="#db2777" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">Cahit Sıtkı Tarancı</text>\n  <text x="32" y="92" font-size="11" fill="#831843">• Unvan: Otuz Beş Yaş Şairi</text>\n  <text x="32" y="114" font-size="11" fill="#831843">• Tema: Ölüm korkusu, yaşama</text>\n  <text x="42" y="130" font-size="11" fill="#831843">sevinci, yalnızlık, zaman</text>\n  <text x="32" y="152" font-size="11" fill="#831843">• Mektup: Ziya\'ya Mektuplar</text>\n  <text x="32" y="176" font-size="11" font-weight="bold" fill="#be185d">Şiir: Ömrümde Sükût, Otuz Beş</text>\n  <text x="32" y="194" font-size="11" font-weight="bold" fill="#be185d">Yaş, Düşten Güzel, Sonrası</text>\n  <rect x="245" y="45" width="210" height="182" rx="10" fill="#e0e7ff" stroke="#4f46e5" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">Ziya Osman Saba</text>\n  <text x="257" y="92" font-size="11" fill="#312e81">• Topluluk: Yedi Meşaleciler</text>\n  <text x="257" y="114" font-size="11" fill="#312e81">• Tema: Çocukluk özlemi, ev-aile</text>\n  <text x="267" y="130" font-size="11" fill="#312e81">huzuru, tevekkül, merhamet</text>\n  <text x="257" y="152" font-size="11" fill="#312e81">• Öykü: Mesut İnsanlar Fotoğ.</text>\n  <text x="257" y="176" font-size="11" font-weight="bold" fill="#4338ca">Şiir: Sebil ve Güvercinler,</text>\n  <text x="257" y="194" font-size="11" font-weight="bold" fill="#4338ca">Geçen Zaman, Nefes Almak</text>\n  <rect x="470" y="45" width="210" height="182" rx="10" fill="#f3e8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Asaf Halet Çelebi</text>\n  <text x="482" y="92" font-size="11" fill="#581c87">• Unvan: Sezgi ve Mistisizm Şairi</text>\n  <text x="482" y="114" font-size="11" fill="#581c87">• Kaynak: Mevlevilik, Budizm,</text>\n  <text x="492" y="130" font-size="11" fill="#581c87">Doğu masalları, bilinçaltı</text>\n  <text x="482" y="152" font-size="11" fill="#581c87">• Yöntem: Somut malzemeyle soyut</text>\n  <text x="482" y="176" font-size="11" font-weight="bold" fill="#7e22ce">Şiir: He, Lamelif,</text>\n  <text x="482" y="194" font-size="11" font-weight="bold" fill="#7e22ce">Om Mani Padme Hum</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
